begin;
create temp table follow_ids(kind text,id uuid);grant select on follow_ids to authenticated;
insert into follow_ids values('tenant',gen_random_uuid()),('other_tenant',gen_random_uuid()),('writer',gen_random_uuid()),('subject',gen_random_uuid()),('fan',gen_random_uuid()),('outsider',gen_random_uuid()),('other_writer',gen_random_uuid());
insert into family_private.tenants(id,code,name,status,contact_phone,contact_email,payment_status)select id,case kind when 'tenant'then 'FOLLOW-TEST'else 'FOLLOW-OTHER'end,'اختبار المتابعة','active','+966500007701',kind||'-follow@example.invalid','waived'from follow_ids where kind in('tenant','other_tenant');
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
select public.platform_action('save',jsonb_build_object('id',id,'status','active','payment_status','waived'))from follow_ids where kind in('tenant','other_tenant');
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data)select id,'authenticated','authenticated',kind||'-follow@example.invalid',now(),jsonb_build_object('family_code',case kind when 'outsider'then 'FOLLOW-OTHER'else 'FOLLOW-TEST'end,'full_name',kind||' احمد حسن اختبار','display_name',kind||' احمد حسن اختبار','gender','male','phone',case kind when 'writer'then '+966500007701'when 'subject'then '+966500007702'when 'fan'then '+966500007703'when 'other_writer'then '+966500007705'else '+966500007704'end)from follow_ids where kind in('writer','subject','fan','outsider','other_writer');
update public.profiles set status='active',role=case when id in(select id from follow_ids where kind in('writer','other_writer'))then 'admin'else 'member'end where id in(select id from follow_ids);
update public.family_settings set journalist_approval=false where tenant_id=(select id from follow_ids where kind='tenant');



create temp table social_test(k text,id text);grant all on social_test to authenticated;
set local role anon;
do $$begin if public.tenant_directory('')<>'[]'::jsonb or public.tenant_directory('اختبار')<>'[]'::jsonb or jsonb_array_length(public.tenant_directory('FOLLOW-TEST'))<>1 then raise exception 'DIRECTORY_LEAK';end if;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='writer'),true);
set local role authenticated;
insert into social_test select 'ticket',public.support_action('create','{"subject":"اختبار الدعم","body":"تفاصيل المشكلة"}')->>'id';
insert into social_test select 'post',(public.community_hub('publish',jsonb_build_object('body','أهلاً @عضو','mentions',jsonb_build_array((select id from follow_ids where kind='fan'))))#>>'{}');
do $$begin if public.community_hub('feed')->0->'mentions'->0->>'id'is distinct from(select id::text from follow_ids where kind='fan')then raise exception 'MENTION_MISSING';end if;
begin perform public.community_hub('publish',jsonb_build_object('body','مرفوض','mentions',jsonb_build_array((select id from follow_ids where kind='outsider'))));raise exception 'MENTION_LEAK';exception when raise_exception then if sqlerrm='MENTION_LEAK'then raise;end if;end;
end$$;
insert into public.posts(author_id,title,body,published,mentioned_member_ids)select auth.uid(),'اختبار التعليقات','نص الخبر',true,array[(select id from follow_ids where kind='fan')];
reset role;
insert into social_test select 'news',id::text from public.posts where title='اختبار التعليقات'and tenant_id=(select id from follow_ids where kind='tenant');
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='subject'),true);
set local role authenticated;
insert into public.likes(post_id,user_id)select id::bigint,auth.uid()from social_test where k='news';
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='other_writer'),true);
set local role authenticated;
insert into public.comments(post_id,author_id,body)select id::bigint,auth.uid(),'تعليق جديد'from social_test where k='news';
reset role;
do $$begin if(select count(*)from family_private.news_comment_alerts where post_id=(select id::bigint from social_test where k='news'))<>3 then raise exception 'COMMENT_RECIPIENTS';end if;end$$;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='fan'),true);
set local role authenticated;
do $$declare result jsonb;begin result:=public.native_notifications('list');if not exists(select 1 from jsonb_array_elements(result->'items')e where e->>'id'like 'comment:%'and e->>'post_id'=(select id from social_test where k='news'))then raise exception 'ALERT_NOT_IN_INBOX';end if;
begin perform public.family_pause(true);raise exception 'MEMBER_PAUSED';exception when raise_exception then if sqlerrm='MEMBER_PAUSED'then raise;end if;end;
begin perform public.support_action('list');raise exception 'MEMBER_SUPPORT';exception when raise_exception then if sqlerrm='MEMBER_SUPPORT'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='outsider'),true);
reset role;
update public.profiles set role='admin'where id=(select id from follow_ids where kind='outsider');
set local role authenticated;
do $$begin if public.support_action('list')<>'[]'::jsonb then raise exception 'SUPPORT_LEAK';end if;
begin perform public.support_action('messages',jsonb_build_object('ticket',(select id from social_test where k='ticket')));raise exception 'THREAD_LEAK';exception when raise_exception then if sqlerrm='THREAD_LEAK'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
set local role authenticated;
select public.support_action('reply',jsonb_build_object('platform',true,'ticket',(select id from social_test where k='ticket'),'body','رد إدارة المنصة'));
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='writer'),true);
set local role authenticated;
do $$declare result jsonb;begin result:=public.support_action('messages',jsonb_build_object('ticket',(select id from social_test where k='ticket')));if jsonb_array_length(result)<>2 or not(result->1->>'from_platform')::boolean then raise exception 'SUPPORT_REPLY';end if;
perform public.family_pause(true);if family_private.access_role()is not null then raise exception 'PAUSE_ACCESS';end if;if public.tenant_current()->>'status'<>'family_paused'then raise exception 'PAUSE_STATUS';end if;
perform public.support_action('list');perform public.family_pause(false);if family_private.access_role()<>'admin'then raise exception 'RESUME_FAILED';end if;end$$;
reset role;
select 'PASS code-only entry, scoped mentions, comment recipients/inbox, support round trip/isolation, manager pause/resume' result;
rollback;
